// Adapted from masterrnative src/screens/transactions/SaleFormScreen.tsx:91-107
// @ d14bebb (the React form shell removed: submitSale takes the context writes and alert
// as injected dependencies; the two AsyncStorage writes are kept as separate failure
// domains per finding F1, so a batch-status failure is never reported as an unsaved sale).
export async function submitSale({ deps, sale, batch, existingSale, sales, mortalityRecords }) {
  const { addSale, updateSale, updatePigBatch, getBatchCurrentQuantity, alert, goBack } = deps;

  try {
    if (existingSale) {
      await updateSale(sale);
    } else {
      await addSale(sale);
    }
  } catch (error) {
    alert('Save failed', 'The sale could not be saved. Please try again.');
    return { saleSaved: false, batchClosed: false };
  }

  // The sale is durably saved from here on. A failure while persisting the derived batch
  // status must not tell the user to retry the sale: a retried add creates a duplicate
  // sale under a new id (finding F1).
  let batchClosed = false;
  try {
    const nextSales = existingSale
      ? sales.map((item) => (item.id === sale.id ? sale : item))
      : [sale, ...sales];
    const remainingQuantity = getBatchCurrentQuantity(batch, nextSales, mortalityRecords);
    if (remainingQuantity === 0 && batch.status === 'active') {
      await updatePigBatch({ ...batch, status: 'sold_out' });
      batchClosed = true;
    }
  } catch (error) {
    alert('Sale saved', 'The sale was recorded, but the batch status could not be updated. Pull to refresh; do not re-enter the sale.');
    goBack();
    return { saleSaved: true, batchClosed: false };
  }

  goBack();
  return { saleSaved: true, batchClosed };
}

