// Adapted from masterrnative src/utils/collection.ts:1-8 and the update path of
// src/screens/transactions/SaleFormScreen.tsx:91-107 @ d14bebb (reduced to
// replaceRecordById plus a saveSaleUpdate orchestrator; the catch translates a
// missing-record failure per the course's step-6 answer instead of one generic retry
// alert).
export function replaceRecordById(records, replacement) {
  const index = records.findIndex((record) => record.id === replacement.id);
  if (index < 0) {
    throw new Error(`Record '${replacement.id}' was not found.`);
  }

  return records.map((record) => (record.id === replacement.id ? replacement : record));
}

export async function saveSaleUpdate({ sales, nextSale, persist, alert }) {
  try {
    const next = replaceRecordById(sales, nextSale);
    await persist(next);
    return { saved: true, stale: false };
  } catch (error) {
    // Step-6 answer: a missing record is a stale identity, not a transient failure.
    // "Try again" cannot succeed, so say what actually happened.
    if (error instanceof Error && error.message.includes('was not found')) {
      alert('Sale no longer exists', `${error.message} It may have been deleted on another screen; the list will refresh.`);
      return { saved: false, stale: true };
    }
    alert('Save failed', 'The sale could not be saved. Please try again.');
    return { saved: false, stale: false };
  }
}

